CREATE OR REPLACE FUNCTION public.expense_confirm_meter(p_id uuid,p_covers jsonb,p_method text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE a public.supplier_accounts%ROWTYPE;x jsonb;BEGIN
SELECT * INTO a FROM public.supplier_accounts WHERE id=p_id FOR UPDATE;IF NOT FOUND OR NOT public.user_has_tenant(auth.uid(),a.tenant_id) OR NOT(public.has_role(auth.uid(),'admin') OR public.has_role(auth.uid(),'manager')) THEN RAISE EXCEPTION 'Expense access required';END IF;
FOR x IN SELECT * FROM jsonb_array_elements(p_covers) LOOP IF NOT public.user_has_venue(auth.uid(),(x->>'venue_id')::uuid) THEN RAISE EXCEPTION 'Venue access required';END IF;END LOOP;
UPDATE public.supplier_accounts SET covers=p_covers,split_method=p_method WHERE id=p_id;
INSERT INTO public.audit_log(tenant_id,user_id,user_display_name,action,entity_type,entity_id,details) VALUES(a.tenant_id,auth.uid(),'Your team','update','supplier_account',a.id::text,jsonb_build_object('before',jsonb_build_object('covers',a.covers,'split_method',a.split_method),'after',jsonb_build_object('covers',p_covers,'split_method',p_method)));END $$;
REVOKE ALL ON FUNCTION public.expense_confirm_meter(uuid,jsonb,text) FROM PUBLIC;GRANT EXECUTE ON FUNCTION public.expense_confirm_meter(uuid,jsonb,text) TO authenticated;
CREATE OR REPLACE FUNCTION public.expense_prepaid_release(p_line uuid) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE l public.prepaid_schedule_lines%ROWTYPE;s public.prepaid_schedules%ROWTYPE;b public.expense_bills%ROWTYPE;BEGIN
SELECT * INTO l FROM public.prepaid_schedule_lines WHERE id=p_line;SELECT * INTO s FROM public.prepaid_schedules WHERE id=l.schedule_id FOR UPDATE;SELECT * INTO b FROM public.expense_bills WHERE id=s.source_bill_id AND tenant_id=s.tenant_id;
IF NOT FOUND OR b.approval_status<>'posted' OR NOT EXISTS(SELECT 1 FROM public.journal_lines WHERE entry_id=s.initial_journal_entry_id AND account_id=s.prepaid_account_id AND debit>=s.total_amount) THEN RAISE EXCEPTION 'Funded prepaid source required';END IF;
IF auth.uid() IS NULL THEN IF current_setting('app.expense_monthend',true) IS DISTINCT FROM 'on' THEN RAISE EXCEPTION 'Scheduler access required';END IF;ELSIF NOT public.user_has_tenant(auth.uid(),s.tenant_id) OR NOT(public.has_role(auth.uid(),'admin') OR public.has_role(auth.uid(),'manager')) OR (s.venue_id IS NOT NULL AND NOT public.user_has_venue(auth.uid(),s.venue_id)) THEN RAISE EXCEPTION 'Expense access required';END IF;
IF l.status='posted' THEN RETURN l.journal_entry_id;END IF;IF l.planned_amount>s.amount_remaining OR l.planned_amount<0 OR (l.period+interval '1 month - 1 day')::date>(now() AT TIME ZONE 'Asia/Hong_Kong')::date THEN RAISE EXCEPTION 'Prepaid release not ready';END IF;
PERFORM public.finance_assert_open(s.tenant_id,(l.period+interval '1 month - 1 day')::date);RETURN public.post_prepaid_line(p_line);END $$;
REVOKE ALL ON FUNCTION public.expense_prepaid_release(uuid) FROM PUBLIC;GRANT EXECUTE ON FUNCTION public.expense_prepaid_release(uuid) TO authenticated;
DO $$ DECLARE def text;BEGIN SELECT pg_get_functiondef('public.expense_monthend_run(uuid,date)'::regprocedure) INTO def;def:=replace(def,'PERFORM public.post_prepaid_line(line.id)','PERFORM public.expense_prepaid_release(line.id)');EXECUTE def;END $$;
CREATE OR REPLACE FUNCTION public.expense_statement_validate() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ DECLARE amount numeric;BEGIN
IF NEW.meta->'statement_check' IS NOT NULL THEN amount:=(NEW.meta->'statement_check'->>'current_charges')::numeric;IF amount IS NULL OR amount<>NEW.total_amount THEN RAISE EXCEPTION 'Statements book current charges only';END IF;END IF;RETURN NEW;END $$;
CREATE TRIGGER expense_statement_validate BEFORE INSERT OR UPDATE OF total_amount,meta ON public.expense_bills FOR EACH ROW EXECUTE FUNCTION public.expense_statement_validate();
CREATE OR REPLACE FUNCTION public.expense_contract_difference() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE r public.expense_recurring_rules%ROWTYPE;m date;expected numeric;BEGIN
IF NEW.recurring_rule_id IS NULL OR NEW.approval_status='posted' THEN RETURN NEW;END IF;SELECT * INTO r FROM public.expense_recurring_rules WHERE id=NEW.recurring_rule_id AND tenant_id=NEW.tenant_id AND is_contract;IF NOT FOUND THEN RETURN NEW;END IF;
m:=date_trunc('month',coalesce(NEW.service_period_start,NEW.period_start,NEW.bill_date))::date;expected:=public.expense_contract_month_amount(r.id,m);
IF abs(NEW.total_amount-expected)>.01 THEN NEW.meta:=coalesce(NEW.meta,'{}')||jsonb_build_object('bani_question',coalesce(r.name,'Contract')||' bill HK$'||NEW.total_amount||' vs contract HK$'||expected||' — increase?');END IF;RETURN NEW;END $$;
CREATE TRIGGER expense_contract_difference BEFORE INSERT OR UPDATE OF total_amount,recurring_rule_id ON public.expense_bills FOR EACH ROW EXECUTE FUNCTION public.expense_contract_difference();